import{_ as a,o as n,c as t,a2 as i}from"./chunks/framework.1lnE8eph.js";const u=JSON.parse('{"title":"Map Controls and Schedule Alignment","description":"","frontmatter":{},"headers":[],"relativePath":"specs/006-map-controls-and-schedule-alignment.md","filePath":"specs/006-map-controls-and-schedule-alignment.md"}'),o={name:"specs/006-map-controls-and-schedule-alignment.md"};function s(l,e,r,c,d,p){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="map-controls-and-schedule-alignment" tabindex="-1">Map Controls and Schedule Alignment <a class="header-anchor" href="#map-controls-and-schedule-alignment" aria-label="Permalink to &quot;Map Controls and Schedule Alignment&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Remove legacy map icon elements, make map actions accessible native controls, and align the schedule timeline with its table rows. Keep shared workspace dependencies explicit and compatible with the Yarn 1 workspace layout.</p><h2 id="workspace-and-module-dependencies" tabindex="-1">Workspace and module dependencies <a class="header-anchor" href="#workspace-and-module-dependencies" aria-label="Permalink to &quot;Workspace and module dependencies&quot;">​</a></h2><ul><li>Declare shared workspace peer providers at the repository root so Yarn 1 can validate workspace dependencies.</li><li>Keep application runtime dependencies explicit, remove the unused Font Awesome custom-element package and registration, and declare the design-system dependency where the map module uses it.</li><li>Use the design-system&#39;s inline SVG icon component for map controls; do not introduce a second icon library or custom-element dependency.</li></ul><h2 id="map-controls" tabindex="-1">Map controls <a class="header-anchor" href="#map-controls" aria-label="Permalink to &quot;Map controls&quot;">​</a></h2><ul><li>Render map control actions as native buttons with accessible names and existing explanatory titles.</li><li>Keep display and measurement popovers operable with native buttons, including expanded state and popup relationships.</li><li>Use inline SVG icons for grid, display, ruler, line, polygon and circle actions.</li><li>Retain the existing map behavior while aligning the route-fit controls to the inline end of the map.</li><li>Use compact SVG bus markers and small stop dots instead of persistent labels.</li><li>Show one marker label on hover; clear it on pointer leave or map movement.</li></ul><h2 id="schedule-presentation" tabindex="-1">Schedule presentation <a class="header-anchor" href="#schedule-presentation" aria-label="Permalink to &quot;Schedule presentation&quot;">​</a></h2><ul><li>Remove the schedule panel heading to reclaim vertical space while retaining the panel&#39;s accessible name and its toolbar.</li><li>Keep route code and route name on one centered line.</li><li>Match the timeline wrapper, Gantt host, internal Gantt row and canvas to the rendered table-cell height. Observe host resizing so non-default row sizes remain aligned.</li><li>Center timeline drawing against the measured chart height, without adding vertical cell padding.</li><li>Draw timeline grid lines in the same five equal intervals as the header axis. Do not use Gantt&#39;s per-instance tick anchor: virtualized rows mount at different times, causing divider drift after sorting, scrolling, or resizing.</li><li>Give custom select options the same corner radius as their input trigger.</li><li>Give floating menu actions the standard button corner radius instead of the badge radius, including the bus stops action and menu links.</li><li>Accept optional parent-provided <code>renderSortIndicator(direction)</code> content. Preserve the default chevron when omitted and use the sorting toolbar&#39;s icons in schedule headers.</li></ul><h2 id="historical-standalone-table-package-requirement" tabindex="-1">Historical standalone table package requirement <a class="header-anchor" href="#historical-standalone-table-package-requirement" aria-label="Permalink to &quot;Historical standalone table package requirement&quot;">​</a></h2><p>This section records the earlier separate-package requirement for provenance. It is superseded by the <a href="./010-mixed-column-sizing">source-workspace ownership requirement</a>; the application workspace is now the sole supported table source.</p><ul><li>The earlier implementation kept reusable table sources synchronized with the standalone <code>airafa/bus-map-table</code> repository.</li><li>Custom sort indicators, their fallback and accessibility behavior, and Gantt canvas sizing were documented in the standalone package&#39;s guides and API reference.</li></ul><h2 id="acceptance-and-validation" tabindex="-1">Acceptance and validation <a class="header-anchor" href="#acceptance-and-validation" aria-label="Permalink to &quot;Acceptance and validation&quot;">​</a></h2><ul><li>Icon rendering tests verify inline SVG output and ensure map icons do not depend on the legacy custom element.</li><li>Both map and schedule modules pass TypeScript checks.</li><li>Architecture checks, workspace lint, design-system tests and the production build pass.</li><li>Browser inspection confirms icon-only map controls have accessible names, the schedule heading is absent, and the Gantt canvas height matches its table cell.</li><li>Regression tests cover default and custom ascending/descending header icons, unlabeled markers by default, and hover-only labels.</li></ul>',14)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
